unitsize(0.3 cm);

pair A, B, C, D, E, F, I;

A = (2,12);
B = (0,0);
C = (14,0);
I = incenter(A,B,C);
D = extension(A,I,B,C);
E = extension(B,I,C,A);
F = extension(C,I,A,B);

draw(A--B--C--cycle);
draw(A--D);
draw(B--E);
draw(C--F);

label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, S);
